using COMSATS.StudentPortal.Web.Data; using COMSATS.StudentPortal.Web.Models; using COMSATS.StudentPortal.Web.ViewModels; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace COMSATS.StudentPortal.Web.Controllers;
[Authorize(Roles = "Student")] public class CoursesController(ApplicationDbContext db, UserManager<ApplicationUser> users) : Controller { public async Task<IActionResult> Index() { var rows = await db.Enrollments.Where(x => x.Student!.ApplicationUserId == users.GetUserId(User)).Include(x => x.CourseOffering).ThenInclude(x => x!.Course).Include(x => x.CourseOffering).ThenInclude(x => x!.Teacher).ThenInclude(x => x!.User).ToListAsync(); return View(new CoursesViewModel { CurrentTerm = DbSeeder.CurrentTerm, Courses = rows.Select(x => new CoursesViewModel.CourseRow(x.Course!.Code,x.Course.Title,x.InstructorName,x.Location,x.Course.CreditHours,x.MidtermMarks,x.MidtermTotal,x.Grade,x.AttendancePercentage,x.SessionsAttended,x.SessionsTotal,x.AttendanceRisk.ToString(),x.Status.ToString())).ToList() }); } }
